"""
This module provides a way to introduce UTE_CONFIG parameters into taf TestLine object.
It was created to have backward-compatibility with UTE_CONFIG after migrating configuration to TAF.
This module (prepare_ute_testline_configuration_data) MUST ONLY be used with new TAF configs that has 4G configuration
and must be backward-compatible. It SHOULD NOT be used with 5G TAF configurations.
"""
from typing import Sequence, Tuple, Callable, Union, Dict, List, Optional, Type  # noqa: F401

from taf.config.testline import TestPc, ue, CommonUnit, PduPort, TestLine, RealEnb  # noqa: F401
from taf.config.testline.legacy._ute_legacy.ute_testline_configuration.schemas.transport import (
    TrsSchema1,
    TrsSchema2, TrsSchema3,
)
from taf.config.testline.legacy._ute_legacy.ute_testline_configuration.ute_config import (
    Host,
    CUS,
    Pdu,
    IPHY,
    FSMr4,
    FSMr3,
    UTE_CONFIG,
)


def prepare_ute_testline_configuration_data(taf_tl_config):
    # type (TestLine) -> TestLine
    """
    Prepares :class:`UTE_CONFIG` like data based on
    :class:`TestLine` input, then adds its elements to the taf config.
    :param TestLine taf_tl_config: :class:`TestLine` object from vanilla TAF configuration.
    :return TestLine: :class:`TestLine` object with additional elements that mimics :class:`UTE_CONFIG` elements
    for backward compatibility
    :rtype TestLine
    """
    host = _create_hosts(taf_tl_config.test_pcs)
    cus, iphy = _create_simulators(taf_tl_config.ues)
    fsm = _create_fsm(taf_tl_config.enbs, taf_tl_config.vlan_ids)
    ute_tl = _create_ute_config(host=host, cus=cus, iphy=iphy, fsm=fsm)
    _merge_tl_configs(taf_tl_config, ute_tl)
    return taf_tl_config


def _create_hosts(test_pcs):
    # type: (Sequence[TestPc]) -> Sequence[Host]
    """Creates UTE :class:`Host` objects based on TAF :class:`TestPc`"""
    hosts = [Host(
        test_pc.default_ssh_connection_details.addr,
        test_pc.default_ssh_connection_details.username,
        test_pc.default_ssh_connection_details.password,
    ) for test_pc in test_pcs]
    return hosts


def _create_pdu(pdu_data):
    # type: (PduPort) -> Pdu
    """Creates :class:`Pdu` object"""
    protocol = pdu_data.pdu.protocol if hasattr(pdu_data.pdu, "protocol") else None
    login = pdu_data.pdu.login if hasattr(pdu_data.pdu, "login") else None
    setup_args = {"addr": pdu_data.pdu.addr,
                  "port": pdu_data.port_no,
                  "device": pdu_data.pdu.vendor}
    if protocol is not None:
        setup_args["protocol"] = protocol
    if login is not None and protocol != "http":
        setup_args["snmp_user"] = login
    pdu = Pdu(**setup_args)
    return pdu


def _create_cus(simulator_data):
    # type: (ue.CUS) -> CUS
    """Creates UTE :class:`CUS` object based on TAF :class:`ue.CUS`"""
    pdu_data = simulator_data.l1.common_units[0].pdu_port
    return CUS(
        _create_pdu(pdu_data),
        simulator_data.l1.common_units[0].hardware_type,
        simulator_data.trs_ip or '10.0.2.2',
    )


def _create_iphy(simulator_data):
    # type: (ue.IPHY) -> Optional[IPHY]
    """Create UTE :class:`IPHY` object based on TAF :class:`ue.IPHY`"""
    pdu_data = simulator_data.pdu_port
    if pdu_data is None:
        return None
    return IPHY(
        _create_pdu(pdu_data),
        simulator_data.trs_ip or '10.0.2.2',
        simulator_data.hardware_type,
    )


def _create_simulators(ues):
    # type: (Sequence[Union[ue.CUS, ue.IPHY]]) -> Tuple[List[CUS], List[IPHY]]
    """
    Creates UTE UE Simulators (:class:`CUS`, :class:`IPHY`) objects based on TAF UEs objects
    (:class:`ue.CUS`, :class:`ue.IPHY`)
    """
    defined_sims = {ue.CUS: _create_cus,
                    ue.IPHY: _create_iphy}
    sims = {ue.CUS: [], ue.IPHY: []}  # type: Dict[Type[Union[ue.CUS, ue.IPHY]], Union[List[CUS], List[IPHY]]]
    if ues is None:
        return [], []
    for sim in ues:
        taf_class = type(sim)
        ute_class_factory = defined_sims.get(taf_class)
        if ute_class_factory is not None:
            new_sim = ute_class_factory(sim)
            sims[taf_class].append(new_sim)
    return sims[ue.CUS], sims[ue.IPHY]


def _get_fsm_factory_method(fsm_name):
    # type: (str) -> Callable[[CommonUnit, RealEnb, PduPort, str], Union[FSMr3, FSMr4]]
    return _create_airscale if fsm_name not in ('FSMF', 'FLEXI') else _create_flexi


def _create_fsm(enbs, vlan_ids):
    # type: (Sequence[RealEnb], str) -> Sequence[Union[FSMr3, FSMr4]]
    """Creates a list of :class:`FSMr3` (Flexi) and :class:`FSMr4` (AirScale) objects"""
    fsms = []
    if enbs is None:
        return []
    for enb in enbs:
        try:
            common_unit = enb.airscale.common_units[0]
        except AttributeError:
            common_unit = enb.system_module.common_units[0]
        fsm_factory = _get_fsm_factory_method(common_unit.hardware_type)
        ute_pdu = _create_pdu(common_unit.pdu_port)
        ute_fsm = fsm_factory(common_unit, enb, ute_pdu, vlan_ids)
        fsms.append(ute_fsm)
    return fsms


def _create_airscale(common_unit, enb, pdu, vlan_ids):
    # type: (CommonUnit, RealEnb, PduPort, str) -> FSMr4
    """Creates AirScale (:class:`FSMr4`) object"""
    fbips = list(iter([True] * len(common_unit.capacity_units) + [False] * 2))
    trs_schemas = {
        '10.0.1.2': TrsSchema1,
        '10.0.1.4': TrsSchema2,
        '10.0.1.6': TrsSchema3,
    }
    trs_ips = trs_schemas.get(enb.trs_ip.v4, TrsSchema1)()
    return FSMr4(
        hw_type=common_unit.hardware_type,
        hw_version=common_unit.hardware_version or 'X21',
        pdu=pdu,
        fbip1=fbips[0],
        fbip2=fbips[1],
        fbip3=fbips[2],
        trs_ip=trs_ips['enb'],
        top_ip=enb.top_ip.v4 or '10.44.136.254',
        vlan_ids=vlan_ids,
        trs_ips=trs_ips,
        oam_ip=enb.oam_ip or '10.0.1.1',
    )


def _create_flexi(common_unit, enb, pdu, vlan_ids):
    # type: (CommonUnit, RealEnb, PduPort, str) -> FSMr3
    """Creates Flexi (:class:`FSMr3`) object"""
    bbmod_pdu_port = list(iter([_create_pdu(unit.pdu_port) if unit.pdu_port else None
                                for unit in common_unit.capacity_units] + [None] * 2))
    return FSMr3(
        pdu=pdu,
        bbmod1_pdu=bbmod_pdu_port[0],
        bbmod2_pdu=bbmod_pdu_port[1],
        trs_ip=enb.trs_ip.v4 or '10.0.1.2',
        top_ip=enb.top_ip.v4 or '10.44.136.254',
        vlan_ids=vlan_ids,
        oam_ip=enb.oam_ip or '10.0.1.1',
    )


def _merge_tl_configs(taf_tl, ute_tl):
    # type: (TestLine, UTE_CONFIG) -> None
    """
    Merges :class:`UTE_CONFIG` and :class:`TestLine` objects under single TAF object.

    :class:`UTE_CONFIG` has all parameters inside '_attributes' which is a dictionary and therefore
    can have "anything" as key.
    :class:`TestLine` have attributes in 'direct' way, therefore it's impossible to simply copy everything.
    In case of TypeError (attr name is an integer), we put it inside container and deal with it through magic methods.
    """
    for attr, val in ute_tl.__dict__['_attributes'].items():
        try:
            setattr(taf_tl, attr, val)
        except TypeError:
            # `attr` is not a valid attribute name
            taf_tl.ute_wmp[attr] = val
    taf_tl.HW_TYPE_MAPPINGS = ute_tl.HW_TYPE_MAPPINGS


def _create_ute_config(**device_configs):
    # type: (Dict[str, Union[IPHY, CUS, FSMr3, FSMr4, Host]]) -> UTE_CONFIG
    """Creates :class:`UTE_CONFIG` based on previously created objects from UTE family."""
    return UTE_CONFIG(**{device: config for device, config in device_configs.items() if config})
